#include <Arduino.h>

String pending;
unsigned long lastByteAt = 0;

void emitMessage() {
  Serial.print("Received: ");
  Serial.println(pending);
  pending = "";
}

void setup() {
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByteAt = millis();
    if (c == '\n') {
      if (pending.length() && pending[pending.length() - 1] == '\r') {
        pending.remove(pending.length() - 1);
      }
      emitMessage();
    } else {
      pending += c;
    }
  }
  if (pending.length() > 0 && (unsigned long)(millis() - lastByteAt) >= 20) {
    emitMessage();
  }
}
